@php($recordRows = $rows->values()->map(fn($row, $index) => $row + ['index' => $index, 'share' => round($row['total'] / max(1, $applicationsCount) * 100, 1)])->all())
<div class="insights-records" x-data="summaryRecordTable(@js($recordRows))">
    <div class="insights-table-tools">
        <div class="insights-search"><i class="ph ph-magnifying-glass" aria-hidden="true"></i><input type="search" x-model.debounce.150ms="query" aria-label="{{ __('Search :category', ['category' => strtolower(__($label))]) }}" placeholder="{{ __('Search :category', ['category' => strtolower(__($label))]) }}"><button type="button" x-show="query.length" x-cloak @click="query = ''" aria-label="{{ __('Clear search') }}"><i class="ph ph-x" aria-hidden="true"></i></button></div>
        <label class="insights-sort"><span>{{ __('Sort by') }}</span><select x-model="sort" aria-label="{{ __('Sort :category', ['category' => strtolower(__($label))]) }}"><option value="total">{{ __('Most applications') }}</option><option value="accepted">{{ __('Most accepted') }}</option><option value="name">{{ __('Name A to Z') }}</option></select></label>
    </div>
    <div class="insights-table-scroll" tabindex="0" role="region" aria-label="{{ __(':category data table', ['category' => __($label)]) }}">
        <table><caption class="sr-only">{{ __('All :value1', ['value1' => strtolower(__($label))]) }}</caption><thead><tr><th scope="col" :aria-sort="sort === 'name' ? 'ascending' : 'none'"><button type="button" @click="sort = 'name'" :class="{ 'is-sorted': sort === 'name' }">{{ __($label) }}<i class="ph ph-sort-ascending" aria-hidden="true"></i></button></th><th scope="col" :aria-sort="sort === 'total' ? 'descending' : 'none'"><button type="button" @click="sort = 'total'" :class="{ 'is-sorted': sort === 'total' }">{{ __('Applications') }}<i class="ph ph-arrow-down" aria-hidden="true"></i></button></th><th scope="col">{{ __('Share') }}</th><th scope="col">{{ __('Interview stages') }}</th><th scope="col" :aria-sort="sort === 'accepted' ? 'descending' : 'none'"><button type="button" @click="sort = 'accepted'" :class="{ 'is-sorted': sort === 'accepted' }">{{ __('Accepted') }}<i class="ph ph-arrow-down" aria-hidden="true"></i></button></th></tr></thead><tbody>
            <template x-for="row in visibleRows" :key="row.index"><tr @pointermove="if ($event.pointerType === 'mouse') { const r = $el.getBoundingClientRect(); $el.style.setProperty('--spot-x', ($event.clientX - r.left) + 'px') }"><th scope="row"><span class="insights-record-name"><span class="insights-company-initial" aria-hidden="true" x-text="initials(row.name)"></span><span x-text="row.name"></span></span></th><td><strong x-text="row.total"></strong></td><td><span class="insights-table-share"><i aria-hidden="true"><span :style="{ width: row.share + '%' }"></span></i><span x-text="row.share + '%'"></span></span></td><td x-text="row.interviews"></td><td><span class="insights-accepted-number" :class="{ 'is-zero': !row.accepted }" x-text="row.accepted"></span></td></tr></template>
        </tbody></table>
        <p class="insights-search-empty" x-show="filteredRows.length === 0" x-cloak role="status">{{ __('No matching records.') }}</p>
