    <div class="insights-table-footer"><p aria-live="polite"><span x-text="firstRow"></span>–<span x-text="lastRow"></span> {{ __('of') }} <span x-text="filteredRows.length"></span></p><div><button type="button" @click="page = Math.max(1, page - 1)" :disabled="page <= 1" aria-label="{{ __('Previous :category page', ['category' => strtolower(__($label))]) }}"><i class="ph ph-caret-left" aria-hidden="true"></i></button><span x-text="page + ' / ' + pageCount"></span><button type="button" @click="page = Math.min(pageCount, page + 1)" :disabled="page >= pageCount" aria-label="{{ __('Next :category page', ['category' => strtolower(__($label))]) }}"><i class="ph ph-caret-right" aria-hidden="true"></i></button></div></div>
